SELECT DISTINCT Z.IdViaje   ,Z.DescripcionViaje   ,Z.Dominio AS [Vehiculo]   ,Z.Origen   ,Z.Destino   ,V.Varchar1 AS [Contrato]   ,Z.KMTeoricos   ,Z.CicloKmTeoricos   ,Z.KmRecorridos AS [Kilometros Recorridos GPS]   ,EV.descripcion AS [Estado Viaje]  FROM dbo.Z_ItinerarioViaje AS Z WITH (NOLOCK)  INNER JOIN dbo.Viaje AS V WITH (NOLOCK) ON V.IdViaje = Z.IdViaje  INNER JOIN dbo.Jornada J WITH (NOLOCK) ON J.IdJornada = V.IdJornada  INNER JOIN dbo.EstadoViaje AS EV WITH (NOLOCK) ON EV.IdEstadoViaje = V.IdEstadoViaje  WHERE EXISTS (    SELECT 1    FROM dbo.EstadoViajeTraceEstado AS T WITH (NOLOCK)    WHERE T.IdViaje = V.IdViaje     AND T.IdEstadoViajeDestino = 99    )   AND J.IdOperacion = 139
